// operator sees exact impact before clicking through.
type FederationDefederationPreview struct {
	// CachedSuggestions federation_peer_suggestions rows sourced from this peer that would be dropped.
	CachedSuggestions int                `json:"cached_suggestions"`
	PeerDisplayName   string             `json:"peer_display_name"`
	PeerId            openapi_types.UUID `json:"peer_id"`
	PeerUrl           string             `json:"peer_url"`

	// PendingHandshakes Number of pending_outbound + pending_inbound rows for this peer.
	PendingHandshakes int `json:"pending_handshakes"`

	// SharesByKind Per-object-kind breakdown so the modal renders
	// "12 posts, 23 collections, 8 assets, …". Keys are
	// from the federation.ShareObjectKind closed catalogue;
	// kinds with zero active shares may be omitted.
	SharesByKind map[string]int64 `json:"shares_by_kind"`

	// TotalActiveShares Sum across all object kinds. The cascade emits one
	// aa:Unshare per row (best-effort delivery via the
	// outbox) before deleting the peer.
	TotalActiveShares int64 `json:"total_active_shares"`
}

